var i=`0336-profiteroles`;var n=`world-0336`;var o=`FR`;var a=`western-europe`;var r=8;var l=58;var s={en:`Profiteroles`,ua:`Профітролі`};var u={en:`A traditional France dish made with all-purpose flour, chicken egg, whole cow milk, egg yolk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко, яєчний жовток. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`water`,260,`ml`],[`unsalted-butter`,110,`g`],[`table-salt`,2,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`all-purpose-flour`,165,`g`],[`chicken-egg`,4,`pcs`]]},{en:`Bake in a preheated 180°C oven for about 28 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 28 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:28,i:[]},{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:9,i:[[`whole-cow-milk`,470,`ml`],[`egg-yolk`,4,`pcs`],[`white-granulated-sugar`,95,`g`],[`cornstarch`,35,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Pipe the cooled vanilla custard into the baked choux buns through a small hole; melt chocolate with cream and spoon over the tops.`,ua:`Наповніть спечені заварні тістечка охолодженим ванільним кремом через невеликий отвір; розтопіть шоколад із вершками та полийте зверху.`,t:[`rolling-stuffed-food`],m:7,i:[[`dark-chocolate`,140,`g`],[`heavy-cream`,150,`ml`]]}];var d={slug:i,id:n,country:`FR`,region:a,servings:8,minutes:58,title:s,text:u,steps:g};export{o as country,d as default,n as id,l as minutes,a as region,r as servings,i as slug,g as steps,u as text,s as title};